blocks = []
for i in range(1,16):
    for j in range(i+1,16):
        k = i ^ j
        if k > j and k < 16:
            blocks.append(sorted([i-1, j-1, k-1]))
blocks = sorted(set(tuple(b) for b in blocks))

inc = [[0]*35 for _ in range(15)]
for b_idx, bl in enumerate(blocks):
    for p in bl:
        inc[p][b_idx] = 1

inc70 = [row + row for row in inc]

flat = [inc70[i][j] for i in range(15) for j in range(70)]
print(flat)
